public class binarytrees {
    private static final class Node {
        final Node left;
        final Node right;

        Node(Node left, Node right) {
            this.left = left;
            this.right = right;
        }
    }

    private static Node bottomUpTree(int depth) {
        if (depth <= 0) {
            return new Node(null, null);
        }
        return new Node(bottomUpTree(depth - 1), bottomUpTree(depth - 1));
    }

    private static int itemCheck(Node node) {
        if (node.left == null) {
            return 1;
        }
        return 1 + itemCheck(node.left) + itemCheck(node.right);
    }

    public static void main(String[] args) {
        int n = Integer.parseInt(args[0]);
        StringBuilder out = new StringBuilder();

        int stretchDepth = n + 1;
        Node stretch = bottomUpTree(stretchDepth);
        out.append("stretch tree of depth ").append(stretchDepth)
           .append("\t check: ").append(itemCheck(stretch)).append('\n');

        Node longLivedTree = bottomUpTree(n);

        int minDepth = 4;
        int maxDepth = n;
        int stretchRange = maxDepth - minDepth;
        if (stretchRange >= 0) {
            int iterations = 1 << (n + minDepth - maxDepth); // 2^(N-d+4)
            for (int depth = minDepth; depth <= maxDepth; depth += 2) {
                int checkSum = 0;
                for (int i = 0; i < iterations; i++) {
                    checkSum += itemCheck(bottomUpTree(depth));
                }
                out.append(iterations).append("\t trees of depth ").append(depth)
                   .append("\t check: ").append(checkSum).append('\n');
                iterations >>= 2; // next depth increases by 2 => divide by 4
            }
        }

        out.append("long lived tree of depth ").append(n)
           .append("\t check: ").append(itemCheck(longLivedTree)).append('\n');

        System.out.print(out.toString());
    }
}

